import { useNavigate } from "react-router-dom";
import {
  ArrowLeft,
  Check,
  ChevronLeft,
  ChevronRight,
  MessageSquareText,
  RotateCcw,
  Sparkles,
} from "lucide-react";
import { useState } from "react";
import { LiquidGlass } from "../reactbits/LiquidGlass";
import AnimatedList from "../reactbits/vendor/AnimatedList/AnimatedList";
import FadeContent from "../reactbits/vendor/FadeContent/FadeContent";
import GlassSurface from "../reactbits/vendor/GlassSurface/GlassSurface";
import SpecularButton from "../reactbits/vendor/SpecularButton/SpecularButton";
import ThoughtLine from "../reactbits/vendor/ThoughtLine/ThoughtLine";
import VoicePill from "../reactbits/vendor/VoicePill/VoicePill";
import { cn } from "../../lib/cn";
import {
  CLASSIC_SCENARIOS,
  classicScenarioById,
} from "../../data/classicScenarios";
import { useInkFlow } from "../../store/inkflow";

export function PracticePage() {
  const navigate = useNavigate();
  const {
    practiceMessages,
    practiceScenarioId,
    practiceCompleted,
    sendPracticeMessage,
    setPracticeScenario,
    resetPractice,
  } = useInkFlow();
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [voiceActive, setVoiceActive] = useState(false);
  const scenario = classicScenarioById(practiceScenarioId);
  const scenarioIndex = CLASSIC_SCENARIOS.findIndex(
    (item) => item.id === practiceScenarioId,
  );
  const moveScenario = (offset: number) => {
    const nextIndex =
      (scenarioIndex + offset + CLASSIC_SCENARIOS.length) %
      CLASSIC_SCENARIOS.length;
    setPracticeScenario(CLASSIC_SCENARIOS[nextIndex]!.id);
  };

  const submit = async (value = message) => {
    const clean = value.trim();
    if (!clean || busy) return;
    setMessage("");
    setBusy(true);
    try {
      await sendPracticeMessage(clean);
    } finally {
      setBusy(false);
    }
  };

  if (practiceCompleted) {
    return (
      <div className="practice-complete">
        <LiquidGlass className="practice-complete__scene" intensity="strong">
          <img src="/leafia-mark.svg" alt="" />
          <span className="eyebrow">Conversation complete · 对话完成</span>
          <h1>Your Language</h1>
          <p>
            The expressions you used under pressure are now ready to return to
            your corpus.
          </p>
          <div className="used-expression-list">
            {scenario.targetExpressions.slice(0, 3).map(
              (expression) => (
                <div key={expression}>
                  <Check size={15} />
                  {expression}
                </div>
              ),
            )}
          </div>
          <p className="practice-complete__count">
            {scenario.targetExpressions.slice(0, 3).length} expressions added
            to your corpus
          </p>
          <div className="practice-complete__actions">
            <SpecularButton
              size="md"
              radius={13}
              textColor="#17181a"
              lineColor="#6a5dff"
              baseColor="#d8d6d0"
              onClick={() => navigate("/corpus")}
            >
              Review
            </SpecularButton>
            <button
              type="button"
              className="secondary-button"
              onClick={resetPractice}
            >
              <RotateCcw size={15} />
              Practice again
            </button>
          </div>
        </LiquidGlass>
      </div>
    );
  }

  return (
    <div
      className="practice-page practice-page--interactive"
      data-motion="enter"
    >
      <aside className="practice-scene">
        <button
          type="button"
          className="icon-button"
          onClick={() => navigate("/shelf")}
          aria-label="Back to room"
        >
          <ArrowLeft size={19} />
        </button>
        <GlassSurface
          width="100%"
          height="100%"
          borderRadius={24}
          backgroundOpacity={0.15}
          saturation={1.4}
          distortionScale={-120}
          className="practice-scene__glass"
        >
          <div className="practice-scene__copy">
            <span className="eyebrow">03 / Use it</span>
            <h1>{scenario.title}</h1>
            <p className="practice-scenario-meta">
              {scenario.author} · {scenario.chapter} · {scenario.character}
            </p>
            <p>
              {scenario.zhTitle} · {scenario.role}
            </p>
            <AnimatedList
              items={scenario.targetExpressions}
              className="practice-target-list"
              itemClassName="practice-target-item"
              showGradients={false}
              displayScrollbar={false}
              enableArrowNavigation={false}
            />
          </div>
        </GlassSurface>
        <div className="practice-scene__status">
          <Sparkles size={16} />
          DeepSeek adapts the conversation to the language you are practicing.
        </div>
      </aside>

      <main className="practice-chat">
        <LiquidGlass as="header" className="practice-chat__header">
          <div>
            <MessageSquareText size={18} />
            <strong>Practice</strong>
          </div>
          <button
            type="button"
            className="ghost-button"
            onClick={() => void submit("Finish the conversation")}
          >
            End practice
          </button>
          <div className="practice-scenario-pager">
            <button
              type="button"
              onClick={() => moveScenario(-1)}
              aria-label="上一本"
            >
              <ChevronLeft size={15} />
            </button>
            <span>
              <strong>{scenario.zhTitle}</strong>
              <small>{scenario.title}</small>
            </span>
            <button
              type="button"
              onClick={() => moveScenario(1)}
              aria-label="下一本"
            >
              <ChevronRight size={15} />
            </button>
          </div>
        </LiquidGlass>

        {busy && (
          <ThoughtLine
            working
            steps={[
              "Reading your answer",
              "Checking target phrases",
              "Drafting feedback",
            ]}
            label="Thinking…"
            glyph="sparkle"
            showTimer
            className="practice-thought"
          />
        )}

        <div className="practice-chat__messages">
          {practiceMessages.map((practiceMessage) => (
            <FadeContent
              key={practiceMessage.id}
              className="practice-message-reveal"
              blur
              duration={420}
              threshold={0}
            >
              <div
                className={cn(
                  "practice-message",
                  practiceMessage.role === "user" && "is-user",
                )}
              >
                <div>{practiceMessage.text}</div>
                {practiceMessage.role === "assistant" &&
                  practiceMessage.textZh && (
                    <p className="practice-message__translation">
                      {practiceMessage.textZh}
                    </p>
                  )}
                {practiceMessage.role === "assistant" &&
                  practiceMessage.explanationZh && (
                    <small className="practice-message__explanation">
                      {practiceMessage.explanationZh}
                    </small>
                  )}
                {practiceMessage.feedback && (
                  <small>{practiceMessage.feedback}</small>
                )}
              </div>
            </FadeContent>
          ))}
        </div>

        <div className="practice-options">
          {scenario.suggestions.map((option) => (
            <button
              type="button"
              key={option}
              onClick={() => void submit(option)}
            >
              {option}
            </button>
          ))}
        </div>

        <LiquidGlass
          as="form"
          className="practice-composer practice-composer--glass"
          onSubmit={(event) => {
            event.preventDefault();
            void submit();
          }}
        >
          <VoicePill
            accentColor={voiceActive ? "#d2493c" : "#6a5dff"}
            iconColor="#4d504d"
            background="#f1f0eb"
            size={34}
            waveform
            reactive="simulated"
            onStart={() => setVoiceActive(true)}
            onStop={() => setVoiceActive(false)}
          />
          <input
            value={message}
            onChange={(event) => setMessage(event.target.value)}
            placeholder="Write your answer…"
          />
          <SpecularButton
            size="sm"
            radius={12}
            textColor="#ffffff"
            lineColor="#8c84ff"
            tint="#6a5dff"
            tintOpacity={0.98}
            baseColor="#6a5dff"
            onClick={() => void submit()}
          >
            Send
          </SpecularButton>
        </LiquidGlass>
      </main>
    </div>
  );
}
